@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--bg:#101513;--panel:#171e1b;--panel2:#1d2521;--line:#303a34;--muted:#87928a;--text:#e9ede8;--accent:#d5fa70;--orange:#f18a5d;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--sans:'DM Sans',sans-serif}*{box-sizing:border-box}body{margin:0;background:#0d110f;color:var(--text);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 50% -20%,#26302a 0,transparent 58%),linear-gradient(90deg,rgba(255,255,255,.012) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.012) 1px,transparent 1px);background-size:auto,36px 36px,36px 36px}.shell{max-width:1460px;margin:auto;padding:0 56px}.topbar{height:66px;border-bottom:1px solid #ffffff15;display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.11em;color:#a6afa8}.brand{display:flex;gap:10px;align-items:center;color:#e8ede7;text-decoration:none;font:800 17px var(--display);letter-spacing:.07em}.brand-light{color:var(--accent);margin-left:4px}.brand-mark{color:var(--accent);font-size:20px}.top-center{display:flex;gap:10px;align-items:center}.live-dot{display:inline-block;width:6px;height:6px;background:#d7fa6f;border-radius:50%;box-shadow:0 0 9px #cafa5b}.top-divider{color:#59645b}.top-right{display:flex;gap:12px;align-items:center}.signal-icon{color:var(--accent);font-size:12px;letter-spacing:-3px}.title-screen{position:relative;display:grid;grid-template-columns:1fr .95fr;min-height:690px;border-bottom:1px solid #ffffff16;overflow:hidden}.title-art{position:relative;min-height:650px;overflow:hidden;background:radial-gradient(ellipse at 46% 60%,#303b32 0,#171d19 42%,#111613 73%)}.title-art:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 50%,#101513 100%),linear-gradient(0deg,#101513 1%,transparent 45%);z-index:2}.art-building{position:absolute;left:21%;bottom:4%;width:48%;height:78%;border:1px solid #63706768;transform:perspective(550px) rotateY(-12deg) skewY(1deg);background:repeating-linear-gradient(0deg,transparent 0 39px,#8ea09231 40px 42px),repeating-linear-gradient(90deg,transparent 0 47px,#8ea09231 48px 50px),linear-gradient(110deg,#37423b,#1d2621 70%);box-shadow:0 0 80px #080a08,inset 20px 0 50px #81918414}.art-building:before{content:'';position:absolute;left:-42px;top:-35px;width:42px;height:100%;background:repeating-linear-gradient(0deg,#39443d 0 38px,#85908644 39px 41px);transform:skewY(-38deg);transform-origin:right;filter:brightness(.7)}.art-building:after{content:'';position:absolute;inset:8% 10%;background:repeating-linear-gradient(0deg,transparent 0 39px,#b8c5a637 40px 43px),repeating-linear-gradient(90deg,transparent 0 47px,#b8c5a637 48px 50px);opacity:.6}.art-building i{position:absolute;z-index:2;width:3px;height:3px;background:#dafa73;box-shadow:0 0 12px 3px #dafa73;opacity:.8}.art-building i:nth-child(1){left:19%;top:20%}.art-building i:nth-child(2){left:74%;top:42%;opacity:.25}.art-building i:nth-child(3){left:44%;top:65%}.art-building i:nth-child(4){left:82%;top:80%;opacity:.3}.art-building i:nth-child(5){left:25%;top:88%;opacity:.35}.art-building i:nth-child(6){left:53%;top:12%;opacity:.5}.art-building i:nth-child(7){left:62%;top:34%;opacity:.2}.art-building i:nth-child(8){left:35%;top:51%;opacity:.35}.art-building i:nth-child(9){left:84%;top:18%;opacity:.35}.art-floor{position:absolute;z-index:3;left:18%;top:26%;font:900 160px/.8 var(--display);color:#eaf1e4;opacity:.08;letter-spacing:-.05em}.art-glow{position:absolute;width:270px;height:220px;bottom:5%;left:30%;border-radius:50%;background:#c9f76818;filter:blur(70px)}.art-grain{position:absolute;inset:0;z-index:2;opacity:.2;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}.art-caption{position:absolute;bottom:34px;left:22px;z-index:4;font:9px var(--mono);letter-spacing:.16em;color:#9da99d}.title-copy{padding:105px 20px 70px 20px;position:relative;z-index:4}.eyebrow{font:10px var(--mono);letter-spacing:.16em;color:#a8b3a8;margin:0 0 19px}.title-copy h1{font:900 clamp(74px,8.5vw,120px)/.77 var(--display);letter-spacing:-.035em;margin:0 0 34px;color:#eff2eb}.title-copy h1 em{font-style:normal;color:var(--accent)}.story{max-width:390px;font-size:14px;line-height:1.75;color:#aab3ab;margin-bottom:27px}.mission-line{display:flex;gap:14px;align-items:center;border-top:1px solid #ffffff1c;padding:17px 0;margin:0 0 25px;max-width:390px}.mission-icon{width:35px;height:35px;border:1px solid #d5fa7070;color:var(--accent);display:grid;place-items:center;font-size:20px}.mission-line b,.mission-line small{display:block}.mission-line b{font:11px var(--mono);letter-spacing:.1em;margin-bottom:5px}.mission-line small{font-size:11px;color:#8f9a91}.primary-button{background:var(--accent);border:0;color:#151c13;padding:15px 20px;min-width:236px;font:700 11px var(--mono);letter-spacing:.1em;cursor:pointer;transition:transform .18s,background .18s}.primary-button span{font-size:17px;margin-left:20px}.primary-button:hover{background:#e2ff99;transform:translateY(-2px)}.control-note{margin-top:24px;color:#7f8981;font:8px var(--mono);letter-spacing:.075em;line-height:1.8}.control-note span{color:var(--accent);padding:0 4px}.title-footer,.site-footer{display:flex;justify-content:space-between;align-items:center;color:#78837a;font:8px var(--mono);letter-spacing:.1em}.title-footer{position:absolute;bottom:19px;left:0;right:0;z-index:5}.title-footer span:nth-child(2){color:#a7b0a7}.game-screen{padding:26px 0 25px}.hidden{display:none!important}.game-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:17px}.game-heading .eyebrow{margin-bottom:5px}.game-heading .eyebrow span{color:var(--accent);padding:0 5px}.game-heading h2{margin:0;font:700 28px var(--display);letter-spacing:.04em}.game-heading h2 span{font:11px var(--mono);color:#9ba59c;letter-spacing:.09em;margin-left:7px}.floor-progress{width:230px}.progress-label{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.1em;color:#a2ada4;margin-bottom:8px}.progress-label b{color:var(--accent)}.progress-label i{font-style:normal;color:#737e75}.progress-track{height:3px;background:#343e37}.progress-track i{height:100%;width:3.3%;display:block;background:var(--accent);transition:width .4s}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 278px;gap:14px}.scene-wrap{position:relative;min-width:0;background:#151b18;border:1px solid #3a453e;overflow:hidden}.scene-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:1000/620;cursor:crosshair}.scene-bottom{height:29px;position:absolute;bottom:0;left:0;right:0;background:#101512e8;border-top:1px solid #ffffff1a;display:flex;align-items:center;justify-content:space-between;padding:0 12px;color:#9ba59b;font:8px var(--mono);letter-spacing:.1em}.scene-bottom .live-dot{width:5px;height:5px;margin-right:6px}.scene-bottom span:last-child{color:var(--accent)}.sidebar{display:flex;flex-direction:column;gap:9px}.side-card{border:1px solid var(--line);background:linear-gradient(140deg,#1b231f,#171d1a);padding:13px 15px}.card-label{font:9px var(--mono);letter-spacing:.11em;color:#a9b3aa;display:flex;align-items:center;gap:7px}.tiny-cross{color:var(--accent);font-size:13px}.status-pill{margin-left:auto;border:1px solid #656d48;color:#d4ed80;padding:3px 6px;font-size:7px;letter-spacing:.08em}.objective-card h3{margin:12px 0 5px;font:600 19px var(--display);letter-spacing:.03em}.objective-card p,.survivor-card p{color:#9aa49c;font-size:10px;line-height:1.55;margin:0}.objective-step{border-top:1px solid #ffffff18;margin-top:12px;padding-top:9px;display:flex;gap:8px;align-items:center;color:#8e9990;font:8px var(--mono);letter-spacing:.1em}.objective-step span:first-child{color:var(--accent);font-size:12px}.survivor-count{display:flex;align-items:baseline;margin:8px 0 3px}.survivor-count>b{font:700 37px/.95 var(--display);color:var(--accent)}.survivor-count>span:nth-child(2){font:12px var(--mono);color:#879188;margin-left:5px}.survivor-person{margin-left:auto;font-size:27px;color:#e3e8dd}.survivor-dots{display:flex;gap:5px;margin-top:10px}.survivor-dots i{width:13px;height:3px;background:#39443b}.survivor-dots i.found{background:var(--accent);box-shadow:0 0 8px #d5fa7060}.vitals-card{padding-bottom:10px}.vital-row{display:flex;align-items:center;gap:7px;margin-top:12px;font:8px var(--mono);letter-spacing:.07em;color:#a6b0a7}.vital-row .meter{height:4px;flex:1;background:#303a33}.meter i{height:100%;display:block;background:var(--accent);width:100%;transition:width .2s}.ammo-meter i{background:#e8bd6d}.vital-row>b{font-size:9px;min-width:48px;text-align:right;color:#e4e9e1}.weapon-row{border-top:1px solid #ffffff18;margin-top:12px;padding-top:10px;display:flex;align-items:center;gap:9px;font:10px var(--mono);color:#e5e9e2}.weapon-row small{display:block;margin-top:4px;font-size:7px;color:#859087}.weapon-icon{font-size:23px;color:#d3f76e}.reload-state{margin-left:auto;color:var(--accent);font-size:7px}.radio-card{position:relative;flex:1;min-height:91px}.radio-wave{color:var(--accent);letter-spacing:-3px}.radio-card p{font-size:10px;line-height:1.55;color:#d1d8d0;margin:10px 0}.radio-card small{font:7px var(--mono);letter-spacing:.08em;color:#8d998f}.side-bottom{margin-top:auto;display:flex;justify-content:space-between;color:#758078;font:7px var(--mono);letter-spacing:.1em;padding:3px 2px}.side-bottom i{font-style:normal;color:var(--accent)}.toast{position:absolute;top:18px;left:50%;transform:translate(-50%,-10px);background:#121915eF;border:1px solid #d5fa7077;padding:9px 14px;color:#e3ebdb;font:9px var(--mono);letter-spacing:.08em;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap;z-index:4}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;left:50%;bottom:49px;transform:translateX(-50%);background:#111712dd;padding:7px 10px;display:flex;gap:8px;align-items:center;font:8px var(--mono);letter-spacing:.1em}.interact-hint span{color:#111;background:var(--accent);padding:4px 6px;font-weight:bold}.mobile-controls{display:none}.end-screen{min-height:650px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.end-symbol{font-size:48px;color:var(--accent);margin-bottom:25px}.end-screen h2{font:900 clamp(44px,7vw,80px)/.9 var(--display);margin:0 0 15px}.end-screen p:not(.eyebrow){color:#a7b2a8;font-size:14px;margin:0 0 30px}.site-footer{height:45px;border-top:1px solid #ffffff17}.site-footer i{font-style:normal;color:var(--accent);padding:0 4px}
@media(max-width:950px){.shell{padding:0 25px}.title-screen{min-height:630px}.title-copy{padding-top:95px}.game-layout{grid-template-columns:minmax(0,1fr) 245px;gap:10px}.side-card{padding:11px}.game-heading h2{font-size:25px}}
@media(max-width:720px){.shell{padding:0 14px}.topbar{height:54px}.top-center{display:none}.top-right{font-size:8px}.title-screen{display:block;min-height:700px}.title-art{position:absolute;inset:0;min-height:auto;opacity:.65}.art-building{left:34%;top:4%;bottom:auto;height:56%;width:50%}.art-floor{left:12%;top:21%;font-size:130px}.title-copy{padding:310px 8px 70px}.title-copy h1{font-size:82px;margin-bottom:20px}.story{font-size:12px;max-width:350px}.mission-line{max-width:350px}.control-note{font-size:7px;max-width:340px}.title-footer span:nth-child(2){display:none}.game-screen{padding-top:17px}.game-heading{align-items:center}.game-heading h2{font-size:23px}.game-heading h2 span{display:block;margin:3px 0 0;font-size:9px}.floor-progress{width:125px}.progress-label{font-size:7px}.game-layout{display:flex;flex-direction:column}.scene-wrap canvas{aspect-ratio:1000/620}.sidebar{display:grid;grid-template-columns:1fr 1fr}.side-card{padding:10px}.objective-card{grid-column:span 2}.radio-card{min-height:100px}.side-bottom{display:none}.scene-bottom{height:24px;font-size:7px;padding:0 7px}.scene-bottom span:nth-child(2){display:none}.mobile-controls{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:6px;margin:10px 0 0}.mobile-controls button{border:1px solid #455047;color:var(--accent);background:#1b231f;min-height:40px;font:10px var(--mono);touch-action:none}.mobile-controls>div{display:grid;grid-template-columns:repeat(3,1fr);gap:3px}.mobile-controls>div button{min-height:40px}.mobile-controls button:active{background:#394638}.survivor-count>b{font-size:31px}.card-label{font-size:8px}.site-footer{font-size:6px;letter-spacing:.05em}.site-footer span:last-child{display:none}.title-footer{font-size:7px}.end-screen{min-height:600px}}
@media(max-width:390px){.sidebar{grid-template-columns:1fr}.objective-card{grid-column:auto}.scene-bottom{font-size:6px}.title-copy h1{font-size:72px}.floor-progress{width:108px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const titleScreen = $('title-screen'), gameScreen = $('game-screen'), endScreen = $('end-screen');
  const W = 1000, H = 620, FLOOR_MAX = 30;
  const survivorFloors = [4, 8, 13, 18, 23, 27];
  const survivorNames = ['Mara · nurse', 'Eli · maintenance', 'June · student', 'Rafi · cook', 'Tomas · courier', 'Nia · engineer'];
  const roomDefs = [
    {x:86,y:65,w:232,h:196,side:'top',name:'NORTH SUITE'}, {x:384,y:65,w:232,h:196,side:'top',name:'WEST SUITE'}, {x:682,y:65,w:232,h:196,side:'top',name:'EAST SUITE'},
    {x:58,y:386,w:204,h:181,side:'bottom',name:'LAUNDRY'}, {x:294,y:386,w:204,h:181,side:'bottom',name:'STORAGE'}, {x:530,y:386,w:204,h:181,side:'bottom',name:'LOUNGE'}, {x:766,y:386,w:176,h:181,side:'bottom',name:'OFFICE'}
  ];
  let player, zombies, survivor, rescued, floor, ammo, reserve, health, keys, aim, shots, particles, pickups, gameState, lastTime, elapsed, toastTimer, fireCooldown, interactCooldown, muzzle, floorSeed, stepSound;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(a,b)=>a+Math.random()*(b-a);
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const roomCenter=(r)=>({x:r.x+r.w/2,y:r.y+r.h/2});
  function isWalkable(x,y,r=8){
    if(x>42+r&&x<W-42-r&&y>278+r&&y<350-r) return true;
    for(const room of roomDefs){
      if(x>room.x+r&&x<room.x+room.w-r&&y>room.y+r&&y<room.y+room.h-r) return true;
      const cx=room.x+room.w/2;
      if(Math.abs(x-cx)<27-r&&room.side==='top'&&y>=room.y+room.h-r&&y<280+r) return true;
      if(Math.abs(x-cx)<27-r&&room.side==='bottom'&&y>348-r&&y<=room.y+r) return true;
    }
    return false;
  }
  function setToast(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastTimer=2.2;}
  function startGame(){
    floor=1;ammo=9;reserve=36;health=100;rescued=[];keys={};aim={x:780,y:310};shots=[];particles=[];pickups=[];elapsed=0;gameState='playing';
    player={x:500,y:315,r:10,angle:0,walk:0,invuln:0};
    titleScreen.classList.add('hidden');endScreen.classList.add('hidden');gameScreen.classList.remove('hidden');
    enterFloor();
  }
  function enterFloor(){
    floorSeed=Math.random()*1000;player.x=500;player.y=315;zombies=[];shots=[];particles=[];pickups=[];survivor=null;
    const count=floor===30?0:Math.min(3+Math.floor(floor/7),7);
    for(let i=0;i<count;i++){
      const room=roomDefs[Math.floor(Math.random()*roomDefs.length)];const c=roomCenter(room);
      zombies.push({x:rand(room.x+24,room.x+room.w-24),y:rand(room.y+24,room.y+room.h-24),r:10,hp:floor>12&&Math.random()<.25?2:1,speed:rand(25,41)+Math.min(floor,20)*.4,attack:0,phase:rand(0,7),hit:0});
    }
    if(Math.random()<.58&&floor<30){pickups.push({x:rand(440,560),y:rand(290,335),type:'ammo',r:9});}
    if(survivorFloors.includes(floor)&&!rescued.includes(survivorFloors.indexOf(floor))){
      const idx=survivorFloors.indexOf(floor),room=roomDefs[(idx*3+1)%roomDefs.length];const c=roomCenter(room);
      survivor={x:c.x+rand(-40,40),y:c.y+rand(-35,35),index:idx, rescued:false, pulse:0};
    }
    $('floor-title').innerHTML=`${floor===1?'LOBBY':floor===30?'ROOFTOP':'FLOOR '+String(floor).padStart(2,'0')} <span>— FLOOR ${String(floor).padStart(2,'0')}</span>`;
    $('floor-count').innerHTML=`${String(floor).padStart(2,'0')} <i>/ 30</i>`;
    $('floor-progress-fill').style.width=`${floor/30*100}%`;
    $('objective-step').textContent=String(floor).padStart(2,'0');
    $('objective-title').textContent=floor===30?'Reach the extraction zone':survivor?'Find the survivor':'Sweep this floor';
    $('objective-copy').textContent=floor===30?'The helicopter is on the roof. Bring everyone to the extraction marker.':survivor?'A life signal is coming from one of the rooms. Find them and press E.':'Clear the floor and find the stairwell to continue your search.';
    $('radio-line').textContent=floor===30?'“We have eyes on you. Get to the roof, now!”':survivor?`“${survivorNames[survivor.index]} here... I can hear them outside.”`:'“If anyone can hear this... we’re on the upper floors. Please.”';
    $('radio-source').textContent=survivor?`SURVIVOR SIGNAL · FLOOR ${String(floor).padStart(2,'0')}`:'UNKNOWN CALLER · WEAK SIGNAL';
    $('floor-weather').textContent=floor===30?'ROOFTOP · EXTRACTION IN PROGRESS':'POWER UNSTABLE · LIGHTS FLICKERING';
    updateHUD();setToast(floor===30?'ROOFTOP ACCESS — EXTRACTION ZONE MARKED':`FLOOR ${String(floor).padStart(2,'0')} — SWEEP IN PROGRESS`);
  }
  function updateHUD(){
    $('rescued-count').textContent=String(rescued.length).padStart(2,'0');
    $('total-survivors').textContent=String(survivorFloors.length).padStart(2,'0');
    $('survivor-status').textContent=rescued.length===6?'ALL ACCOUNTED':`${6-rescued.length} MISSING`;
    $('survivor-copy').textContent=rescued.length===6?'Everyone is with you. Get to the roof.':`${rescued.length} found · ${6-rescued.length} still out there.`;
    $('survivor-dots').innerHTML=survivorFloors.map((_,i)=>`<i class="${rescued.includes(i)?'found':''}"></i>`).join('');
    $('health-fill').style.width=`${health}%`;$('health-value').textContent=Math.ceil(health);
    $('ammo-fill').style.width=`${Math.max(0,ammo/9*100)}%`;$('ammo-value').textContent=`${String(ammo).padStart(2,'0')} / ${reserve}`;
    $('ammo-scene').textContent=`${ammo} / ${reserve}`;
  }
  function shoot(){
    if(gameState!=='playing'||fireCooldown>0)return;
    if(ammo<=0){setToast('EMPTY — PRESS R TO RELOAD');fireCooldown=.22;return;}
    ammo--;fireCooldown=.24;player.angle=Math.atan2(aim.y-player.y,aim.x-player.x);muzzle=.09;
    shots.push({x:player.x+Math.cos(player.angle)*15,y:player.y+Math.sin(player.angle)*15,vx:Math.cos(player.angle)*650,vy:Math.sin(player.angle)*650,life:.5});
    let target=null,best=Infinity;
    for(const z of zombies){const dx=z.x-player.x,dy=z.y-player.y,d=Math.hypot(dx,dy),ang=Math.atan2(dy,dx),diff=Math.atan2(Math.sin(ang-player.angle),Math.cos(ang-player.angle));if(d<430&&Math.abs(diff)<.12+d*.00028&&d<best){best=d;target=z;}}
    if(target){target.hp--;target.hit=.16;for(let i=0;i<7;i++)particles.push({x:target.x,y:target.y,vx:rand(-60,60),vy:rand(-60,60),life:rand(.16,.42),color:'#d66e53'});if(target.hp<=0){zombies=zombies.filter(z=>z!==target);for(let i=0;i<6;i++)particles.push({x:target.x,y:target.y,vx:rand(-45,45),vy:rand(-55,55),life:rand(.25,.55),color:'#83904f'});if(Math.random()<.22)pickups.push({x:target.x,y:target.y,type:'ammo',r:8});}}
    updateHUD();
  }
  function reload(){if(ammo>=9||reserve<=0||gameState!=='playing')return;$('reload-state').textContent='RELOADING';setTimeout(()=>{if(gameState==='playing'){$('reload-state').textContent='READY';const take=Math.min(9-ammo,reserve);ammo+=take;reserve-=take;updateHUD();}},850);}
  function interact(){
    if(gameState!=='playing'||interactCooldown>0)return;
    interactCooldown=.3;
    if(survivor&&distance(player,survivor)<35){
      if(!rescued.includes(survivor.index)){rescued.push(survivor.index);setToast(`${survivorNames[survivor.index].toUpperCase()} JOINED YOUR GROUP`);$('radio-line').textContent='“Thank you. I thought I was the only one left.”';$('radio-source').textContent='SURVIVOR FOUND · SIGNAL LOST';survivor=null;updateHUD();$('objective-title').textContent='Sweep this floor';$('objective-copy').textContent='Clear threats and locate the stairwell to continue your search.';}return;
    }
    const pickup=pickups.find(p=>distance(player,p)<30);
    if(pickup){if(pickup.type==='ammo'){reserve+=12;setToast('AMMO SECURED · +12 ROUNDS');}pickups=pickups.filter(p=>p!==pickup);updateHUD();return;}
    if(floor===30&&distance(player,{x:500,y:128})<58){if(rescued.length===6){gameState='won';$('end-title').textContent='THE ROOF IS YOURS.';$('end-copy').textContent='All six survivors made it. The city still has a heartbeat.';showEnd();}else setToast(`${6-rescued.length} SURVIVOR${6-rescued.length===1?'':'S'} STILL MISSING`);return;}
    if(floor<30&&distance(player,{x:952,y:314})<48){if(zombies.length){setToast('STAIRWELL BLOCKED — CLEAR THE FLOOR');return;}floor++;enterFloor();return;}
    if(floor===30&&distance(player,{x:500,y:128})>=58)setToast('MOVE TO THE HELIPAD');
