function startGame(){floor=1;ammo=9;reserve=36;health=100;rescued=[];keys={};playing=true;titleScreen.classList.add('hidden');endScreen.classList.add('hidden');gameScreen.classList.remove('hidden');yaw=0;pitch=0;player=new THREE.Vector3(0,1.65,9);buildFloor();resize();if(window.matchMedia('(pointer: fine)').matches)canvas.requestPointerLock?.();}
function animate(){requestAnimationFrame(animate);if(!renderer)return;const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;if(playing){movePlayer(dt);fireCooldown=Math.max(0,fireCooldown-dt);interactCooldown=Math.max(0,interactCooldown-dt);recoil=Math.max(0,recoil-dt);if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){reloadTimer=0;$('reload-state').textContent='READY';const take=Math.min(9-ammo,reserve);ammo+=take;reserve-=take;updateHUD();}}camera.position.copy(player);camera.rotation.set(pitch+recoil*.015,yaw,0,'YXZ');for(const z of zombies){z.userData.attack=Math.max(0,z.userData.attack-dt);const d=z.position.distanceTo(player);if(d>1.3){const dir=player.clone().sub(z.position).setY(0).normalize();z.position.addScaledVector(dir,z.userData.speed*dt);z.lookAt(player.x,z.position.y,player.z);}if(d<1.5&&z.userData.attack<=0){z.userData.attack=.9;health=Math.max(0,health-12);updateHUD();setToast('YOU’RE HIT — KEEP YOUR DISTANCE');if(health<=0)showEnd('THE SIGNAL WENT QUIET.','You made it to floor '+floor+'. '+rescued.length+' of 6 survivors came with you.');}}for(const s of survivors)s.position.y=.1+Math.sin(elapsed*3+s.userData.index)*.04;for(const p of pickups)p.position.y=.25+Math.sin(elapsed*4+pickups.indexOf(p))*.05;const near=(survivors.some(s=>s.position.distanceTo(player)<2.2)||pickups.some(p=>p.position.distanceTo(player)<1.8)||(floor<30&&stair&&player.distanceTo(stair)<2)||(floor===30&&extraction&&player.distanceTo(extraction)<3));$('interact-hint').classList.toggle('hidden',!near);}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const k=e.code||e.key.toLowerCase();if(!e.repeat&&k==='KeyE')interact();if(!e.repeat&&k==='KeyR')reload();if(!e.repeat&&(k==='Space'||k==='KeyF'))shoot();keys[k]=true;});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('[data-dir]').forEach(btn=>{const k={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[btn.dataset.dir];const down=e=>{e.preventDefault();keys[k]=true;};const up=e=>{e.preventDefault();keys[k]=false;};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointerleave',up);btn.addEventListener('pointercancel',up);});
$('mobile-fire').addEventListener('pointerdown',e=>{e.preventDefault();shoot();});
$('mobile-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact();});

